namespace NotificationsApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();

    private readonly string[] _templates =
    [
        "Your build completed successfully.",
        "New comment on pull request #42.",
        "Deployment to staging finished.",
        "Disk usage exceeded 80% on web-01.",
        "User 'alice' requested access to repo.",
        "Scheduled backup completed.",
        "Security scan found 0 vulnerabilities.",
        "New release v2.4.1 is available.",
        "CI pipeline failed for branch 'feature/auth'.",
        "Database migration applied successfully."
    ];

    /// <summary>Returns an initial batch of notifications (called during SSR).</summary>
    public List<NotificationItem> GetInitialNotifications()
    {
        lock (_lock)
        {
            return Enumerable.Range(0, 3)
                .Select(_ => CreateNotification())
                .ToList();
        }
    }

    /// <summary>Simulates checking for new notifications. Returns 0-1 new items.</summary>
    public List<NotificationItem> CheckForNew()
    {
        lock (_lock)
        {
            // ~50 % chance of a new notification each poll
            if (Random.Shared.Next(2) == 0)
                return [];

            return [CreateNotification()];
        }
    }

    private NotificationItem CreateNotification()
    {
        var id = _nextId++;
        return new NotificationItem
        {
            Id = id,
            Message = _templates[id % _templates.Length],
            Timestamp = DateTime.UtcNow
        };
    }
}

