@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationService
@inject PersistentComponentState PersistentState
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary rounded-pill">@_notifications.Count</span></h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted ms-3 text-nowrap">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<NotificationItem> _notifications = new();
    private CancellationTokenSource? _cts;
    private PersistingComponentStateSubscription _persistSub;

    protected override void OnInitialized()
    {
        _persistSub = PersistentState.RegisterOnPersisting(PersistNotifications);

        // Try to restore state persisted from the SSR pass.
        // If found, we skip the service call — the data is already here.
        if (PersistentState.TryTakeFromJson<List<NotificationItem>>(
                "notifications", out var restored))
        {
            _notifications = restored!;
        }
        else
        {
            // First (SSR) render — load from service and persist for the interactive pass.
            _notifications = NotificationService.GetInitialNotifications();
        }
    }

    private Task PersistNotifications()
    {
        PersistentState.PersistAsJson("notifications", _notifications);
        return Task.CompletedTask;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        // OnAfterRender only fires on the interactive circuit — never during SSR.
        _cts = new CancellationTokenSource();
        _ = PollForNotificationsAsync(_cts.Token);
        await Task.CompletedTask;
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            var newItems = NotificationService.CheckForNew();
            if (newItems.Count > 0)
            {
                await InvokeAsync(() =>
                {
                    _notifications.AddRange(newItems);
                    StateHasChanged();
                });
            }
        }
    }

    public void Dispose()
    {
        _persistSub.Dispose();
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

